mapper.select:
select t.id, t.avatar, t.nick_name, t.sex, t.birth_date, t.birth_date as birthFormatDate, t.height, t.home_town, t.residential_city, t.job_mes, t.salarys, t.personal_photo, t.id_auth, t.edu_auth, t.school, t.education, t.user_type, t.lately_time, t.create_time, t.city, t.main_city, t.county
,CASE WHEN t.lon IS NOT NULL AND t.lat IS NOT NULL THEN ST_Distance_Sphere( POINT(#{lon}, #{lat}), POINT(t.lon, t.lat) ) ELSE NULL END AS distance
,CASE WHEN t.city=#{city} and t.main_city=true THEN 1 WHEN t.city=#{city} THEN 2 ELSE 3 END AS citySort
,CASE WHEN t.city=#{city} and t.main_city=true THEN 1 WHEN t.city=#{city} THEN 2 ELSE 3 END AS citySort
,CASE WHEN t.city=#{city} and t.county=#{county} THEN 1 WHEN t.city=#{city} THEN 2 ELSE 3 END AS citySort
,1 AS citySort
/*,case when t.lately_time is not null and DATEDIFF(NOW(), t.lately_time)<=180 then 1 else 2 end AS latelySort*/ ,1 as latelySort from t_user t
t.del_flag = 0 and t.`status` = 'ENABLE' and t.invisible='2' and t.photo_auth in ('2','3') and t.recommend='1'
and (t.residential_city like #{residentialCity} or t.user_type='2' or t.tend_live_city like #{residentialCity})
and DATE_FORMAT(birth_date, '%Y') >= #{minAge}
and DATE_FORMAT(birth_date, '%Y') <= #{maxAge}
and t.height >= #{minHeight}
and t.height <= #{maxHeight}
and t.similarity >= #{similarity}
and t.id_auth = '3'
and t.camera_img is not null
and t.tend_live_city like #{tendLiveCity}
and
t.fond_tags like '%${label}%'
and t.job_mes = '学生'
and t.job_mes != '学生'
and t.education = #{education}
and t.home_town like #{homeTown}
and (select count(1) from user_shield ush where ush.user_id=t.id and ush.shield_id=#{ownerId} and ush.del_flag=0)=0 and t.id != #{ownerId}
and t.sex = #{sex}
and t.id in
#{iditem}
and t.id not in
#{iditem}
order by citySort asc,t.sort desc,latelySort asc,t.nature_sort desc,t.id desc
order by t.create_time desc,t.id desc
order by latelySort asc,distance IS NULL, distance ASC,t.id desc
order by t.sort desc,t.lately_time desc,t.id desc

select fu.id, fu.create_time, fu.status, fu.avatar, fu.nick_name, fu.sex, fu.residential_city, fu.id_auth as waitApprovedStatus, fu.user_type, fu.lately_time from t_user fu
fu.del_flag=0
and fu.id_auth=#{authStatus}
and fu.user_type=#{userType}
order by fu.lately_time desc

select fu.id, fu.create_time, fu.status, fu.head_portrait, fu.nick_name, fu.gender, fu.city, fu.additional->>'$.identityAuth' as identityAuth, fu.user_type, fu.lately_time from fr_user fu
fu.del_flag=0
and fu.additional->>'$.identityAuth'=#{authStatus}
and fu.user_type=#{userType}
order by fu.lately_time desc

select fu.id, fu.create_time, fu.status, fu.avatar, fu.nick_name, fu.sex, fu.residential_city, fu.edu_auth, fu.user_type, fu.lately_time from t_user fu
fu.del_flag=0
and fu.edu_auth=#{authStatus}
and fu.user_type=#{userType}
order by fu.lately_time desc

select fu.id, fu.create_time, fu.status, fu.avatar as headPortrait, fu.nick_name, fu.sex as gender, fu.residential_city as city, fu.user_type, fu.lately_time, fu.id_auth as authStatus, fu.edu_auth, fu.photo_auth, fu.phone, rd.distribution_person_id, rd.type, rd.pay_status, rd.higher_pay_status, rd.reward_status, rd.higher_reward_status, tuu.phone as distributionPhone, case when rd.type='1' then dp.`name` when rd.type='2' then tuu.nick_name end as distributionName, tuuu.nick_name as distributionLastNickName, tuuu.phone as distributionLastPhone, (select count(1) from register_distribution srd left join t_user su on srd.user_id=su.id where srd.type=2 and srd.distribution_person_id=fu.id) as distributionCount, (select count(1) from register_distribution ssrd left join t_user ssu on ssrd.user_id=ssu.id left join register_distribution ssrdd on ssrd.distribution_person_id=ssrdd.user_id where ssrd.type=2 and ssrdd.distribution_person_id=fu.id) as nextDistributionCount, (select sum(wr.amount) from withdrawal_record wr where wr.del_flag=0 and wr.user_id=fu.id) as amount from t_user fu left join register_distribution rd on fu.id=rd.user_id left join register_distribution rddd on rd.distribution_person_id=rddd.user_id left join t_user tuu on tuu.id=rd.distribution_person_id left join t_user tuuu on tuuu.id=rddd.distribution_person_id left join distribution_person dp on dp.id=rd.distribution_person_id
fu.del_flag=0
and fu.user_type=#{userType}
and fu.nick_name like #{nickName}
and fu.id=#{userId}
and fu.sex=#{gender}
and fu.residential_city like #{city}
and fu.status=#{status}
and fu.id_auth=#{authStatus}
and DATE_FORMAT(fu.create_time, '%Y-%m-%d %T')>= DATE_FORMAT(#{createTimeStart}, '%Y-%m-%d 00:00:00')
and DATE_FORMAT(fu.create_time, '%Y-%m-%d %T')<= DATE_FORMAT(#{createTimeEnd}, '%Y-%m-%d 23:59:59')
and DATE_FORMAT(fu.lately_time, '%Y-%m-%d %T')>= DATE_FORMAT(#{latelyTimeStart}, '%Y-%m-%d 00:00:00')
and DATE_FORMAT(fu.lately_time, '%Y-%m-%d %T')<= DATE_FORMAT(#{latelyTimeEnd}, '%Y-%m-%d 23:59:59')
and fu.phone like #{phone}
and tuu.phone like #{distributionPhone}
and (tuu.nick_name like #{distributionName} or dp.`name` like #{distributionName})
and rd.type=#{shareType}
and tuuu.phone like #{distributionLastPhone}
order by fu.lately_time desc,fu.id desc
